import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useCart } from '../../context/CartContext';
import { userService } from '../../services/userService';
import toast from 'react-hot-toast';
import './Wishlist.css';

const fmt = (value) =>
  Number(value || 0).toLocaleString('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 });

const Wishlist = () => {
  const { addToCart } = useCart();
  const [wishlistItems, setWishlistItems] = useState([]);
  const [loading, setLoading] = useState(true);

  const load = async () => {
    setLoading(true);
    try {
      const items = await userService.getWishlist();
      setWishlistItems(items || []);
    } catch (err) {
      toast.error(err.response?.data?.message || 'Could not load wishlist.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const remove = async (productId) => {
    try {
      await userService.removeFromWishlist(productId);
      toast.success('Removed from wishlist.');
      await load();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Could not remove item.');
    }
  };

  if (loading) {
    return (
      <div className="wishlist-page container">
        <div className="empty-state">
          <h3>Loading wishlist…</h3>
        </div>
      </div>
    );
  }

  if (wishlistItems.length === 0) {
    return (
      <div className="wishlist-page container">
        <div className="empty-state">
          <h3>Your wishlist is empty</h3>
          <p>Save items to your wishlist to see them here</p>
          <Link to="/products" className="btn btn-primary">Continue Shopping</Link>
        </div>
      </div>
    );
  }

  return (
    <div className="wishlist-page container">
      <h1>Your Wishlist ({wishlistItems.length})</h1>

      <div className="wishlist-grid">
        {wishlistItems.map(product => {
          const isOutOfStock = product.stock === 0 || product.quantity === 0;
          const hasDiscount = product.originalPrice && product.originalPrice > product.price;
          const inStock = product.stock > 0 && product.quantity > 0;

          return (
            <div className="wishlist-card" key={product._id}>
              {isOutOfStock && (
                <span className="out-of-stock-badge">Out of Stock</span>
              )}
              {hasDiscount && (
                <span className="price-drop-badge">
                  {Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100)}% off
                </span>
              )}

              <Link to={`/products/${product._id}`} className="wishlist-img">
                <img 
                  src={product.images?.[0]?.url || product.image || '/placeholder.png'} 
                  alt={product.name} 
                />
              </Link>

              <div className="wishlist-info">
                <Link to={`/products/${product._id}`} className="wishlist-name">
                  {product.name}
                </Link>

                <div className="wishlist-price">
                  {hasDiscount && (
                    <span className="original-price">{fmt(product.originalPrice)}</span>
                  )}
                  {fmt(product.price)}
                  {hasDiscount && (
                    <span className="discount">Save {fmt(product.originalPrice - product.price)}</span>
                  )}
                </div>

                <div className={`stock-status ${inStock ? (product.stock < 10 ? 'low-stock' : 'in-stock') : 'out-of-stock'}`}>
                  {inStock ? (product.stock < 10 ? `Only ${product.stock} left` : 'In Stock') : 'Out of Stock'}
                </div>

                <div className="wishlist-actions">
                  <button 
                    className="btn btn-primary btn-sm" 
                    onClick={() => addToCart(product)}
                    disabled={!inStock}
                  >
                    Add to Cart
                  </button>
                  <button 
                    className="btn btn-outline btn-sm" 
                    onClick={() => remove(product._id)}
                  >
                    Remove
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Wishlist;
